<template><div class="page-shell"><div class="page-heading"><div><h1>操作日志</h1><p>关键业务操作自动留痕，便于追溯审核人与操作时间。</p></div></div><section class="panel"><div class="toolbar"><el-input v-model="query.keyword" clearable placeholder="操作人、动作或详情" style="width:260px"/><el-select v-model="query.module" clearable placeholder="业务模块" style="width:160px"><el-option v-for="m in modules" :key="m" :label="m" :value="m"/></el-select><el-button @click="load"><el-icon><Search/></el-icon>查询</el-button></div><div class="table-wrap"><el-table :data="page.records" v-loading="loading"><el-table-column prop="createdAt" label="操作时间" width="175"/><el-table-column prop="operatorName" label="操作人" width="110"/><el-table-column prop="module" label="业务模块" width="120"/><el-table-column prop="action" label="操作动作" width="130"/><el-table-column prop="detail" label="操作详情" min-width="260"/><el-table-column prop="ipAddress" label="IP地址" width="130"><template #default="s"><span class="mono">{{s.row.ipAddress}}</span></template></el-table-column><el-table-column label="结果" width="90"><template #default><el-tag type="success">成功</el-tag></template></el-table-column></el-table><div class="pagination"><el-pagination v-model:current-page="query.pageNum" :total="page.total" layout="total,prev,pager,next" @current-change="load"/></div></div></section></div></template>
<script setup>import{onMounted,reactive,ref}from'vue';import http from'../api/http';const modules=['登录','用户管理','社区管理','楼栋管理','房屋管理','智慧门牌','承租人管理','入住审核','居住证管理','巡查管理','通知公告','个人中心'],query=reactive({pageNum:1,pageSize:10,keyword:'',module:''}),page=reactive({records:[],total:0}),loading=ref(false);onMounted(load);async function load(){loading.value=true;try{Object.assign(page,await http.get('/logs',{params:query}))}finally{loading.value=false}}</script>
